ztpf_automation_actions.script:
config system interface
  edit {{input.lo_name}}
    set vdom root
    set type loopback
    {%- if net %}
    set ip {{input.lo_ip}}/32
    {%- endif %}
    set allowaccess {{data.allowaccess_loopbacks|join(" ")}}
    set description "Test Looopback {{input.lo_name}} for {{record.device.name}}." 
  next
end

ztpf_templates.script:
config system interface
  edit {{input.interface_name}}
    set type loopback
    set ip {{input.ip_address}} {{input.subnet_mask}}
  next
end
